import{_ as a,o as e,c as t,ae as n}from"./chunks/framework.Co1PSFSm.js";const u=JSON.parse('{"title":"","description":"Routes are the basic building block of Fresh applications. They are used to define the behaviour the application when a given path is requested.\\n","frontmatter":{"description":"Routes are the basic building block of Fresh applications. They are used to define the behaviour the application when a given path is requested.\\n"},"headers":[],"relativePath":"zh/latest/latest/concepts/file-routing.md","filePath":"zh/latest/latest/concepts/file-routing.md"}'),i={name:"zh/latest/latest/concepts/file-routing.md"};function o(p,s,l,d,c,r){return e(),t("div",null,[...s[0]||(s[0]=[n(`<p>Use the <code>.fsRoutes()</code> helper on the <a href="/docs/concepts/app.html"><code>App</code></a> instance to specify where file based routes should be inserted. It adds routes based on the structure in the <code>routes/</code> folder in your project (or any other folder you have specified when instantiating the <a href="/docs/advanced/vite.html"><code>fresh()</code> vite plugin</a>. in <code>vite.config.ts</code>). When you add a new file there, it will register a new route automatically.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { App, staticFiles } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;fresh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> app</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> App</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ basePath: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/foo&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">staticFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">())</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fsRoutes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// This inserts all file based routes here</span></span></code></pre></div><blockquote><p>[info]: The <code>staticFiles()</code> middleware is required when using file based routing. Otherwise the necessary JavaScript files for <a href="/docs/concepts/islands.html">islands</a> won&#39;t be served to the browser.</p></blockquote><p>Example project structure:</p><div class="language-txt-files vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt-files</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;project root&gt;</span></span>
<span class="line"><span>├── deno.json</span></span>
<span class="line"><span>├── main.ts</span></span>
<span class="line"><span>├── vite.config.ts</span></span>
<span class="line"><span>└── routes</span></span>
<span class="line"><span>    ├── (marketing)  # Route group, used to group related routes</span></span>
<span class="line"><span>    │   ├── _layout.tsx  # Apply layout to all routes in this directory</span></span>
<span class="line"><span>    │   ├── about.tsx    # /about route</span></span>
<span class="line"><span>    │   ├── career.tsx   # /career route</span></span>
<span class="line"><span>    │   ├── (_components)  # related components</span></span>
<span class="line"><span>    │   │   └── newsletter-cta.tsx</span></span>
<span class="line"><span>    │   └── (_islands)  # Local island directory</span></span>
<span class="line"><span>    │       └── interactive-stats.tsx # Fresh treats this as an island</span></span>
<span class="line"><span>    └── shop</span></span>
<span class="line"><span>        ├── (_components)</span></span>
<span class="line"><span>        │   └── product-card.tsx</span></span>
<span class="line"><span>        ├── (_islands)</span></span>
<span class="line"><span>        │   └── cart.tsx # Fresh treats this as an island</span></span>
<span class="line"><span>        └── index.tsx</span></span></code></pre></div><p><strong>Special directories inside <code>routes/</code>:</strong></p><ul><li><strong><code>(_islands)</code></strong> - Files in this directory are treated as <a href="/docs/concepts/islands.html">islands</a>, just like files in the top-level <code>islands/</code> folder. This lets you co-locate islands next to the routes that use them.</li><li><strong><code>(_components)</code></strong> - A conventional directory for non-island components that are only used by nearby routes. Fresh does not treat these files specially - the parentheses just prevent them from becoming routes.</li></ul><p>File names are mapped to route patterns as follows:</p><ul><li>File extensions are ignored.</li><li>Literals in the file path are treated as string literals to match.</li><li>Files named <code>&lt;path&gt;/index.&lt;ext&gt;</code> behave identically to a file named <code>&lt;path&gt;.&lt;ext&gt;</code>.</li><li>Path segments can be made dynamic by surrounding an identifier with <code>[</code> and <code>]</code>.</li><li>Paths where the last path segment follows the structure <code>[...&lt;ident&gt;]</code> are treated as having a wildcard suffix.</li></ul><p>Here is a table of file names, which route patterns they map to, and which paths they might match:</p><table tabindex="0"><thead><tr><th>File name</th><th>Route pattern</th><th>Matching paths</th></tr></thead><tbody><tr><td><code>index.ts</code></td><td><code>/</code></td><td><code>/</code></td></tr><tr><td><code>about.ts</code></td><td><code>/about</code></td><td><code>/about</code></td></tr><tr><td><code>blog/index.ts</code></td><td><code>/blog</code></td><td><code>/blog</code></td></tr><tr><td><code>blog/[slug].ts</code></td><td><code>/blog/:slug</code></td><td><code>/blog/foo</code>, <code>/blog/bar</code></td></tr><tr><td><code>blog/[slug]/comments.ts</code></td><td><code>/blog/:slug/comments</code></td><td><code>/blog/foo/comments</code></td></tr><tr><td><code>old/[...path].ts</code></td><td><code>/old/:path*</code></td><td><code>/old/foo</code>, <code>/old/bar/baz</code></td></tr><tr><td><code>docs/[[version]]/index.ts</code></td><td><code>/docs{/:version}?</code></td><td><code>/docs</code>, <code>/docs/latest</code>, <code>/docs/canary</code></td></tr><tr><td><code>[[name]].ts</code></td><td><code>/{:name}?</code></td><td><code>/</code>, <code>/foo</code>, <code>/bar</code></td></tr></tbody></table><p>Advanced use-cases can require that a more complex pattern be used for matching. A custom <a href="https://developer.mozilla.org/en-US/docs/Web/API/URL_Pattern_API" target="_blank" rel="noreferrer">URL pattern</a> can be specified in the route configuration. This pattern will be used instead of the file path based pattern:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { RouteConfig } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;fresh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> config</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> RouteConfig</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  routeOverride: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/x/:module@:version/:path*&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ...</span></span></code></pre></div><p>You can also load additional CSS files for a specific route by exporting a <code>css</code> array. This is a top-level export, separate from <code>config</code>:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> css</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./assets/dashboard.css&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><h2 id="route-groups" tabindex="-1">Route Groups <a class="header-anchor" href="#route-groups" aria-label="Permalink to &quot;Route Groups&quot;">​</a></h2><p>When working with <a href="/docs/advanced/layouts.html">layouts</a> or <a href="/docs/concepts/middleware.html">middlewares</a>, you&#39;ll sometimes come across a situation where you want your routes to inherit from a layout other than what&#39;s suggested by the URL segment.</p><p>Let&#39;s illustrate that with an example:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/about -&gt; layout A</span></span>
<span class="line"><span>/career -&gt; layout A</span></span>
<span class="line"><span>/archive -&gt; layout B</span></span>
<span class="line"><span>/contact -&gt; layout B</span></span></code></pre></div><p>Without any way to group routes this is a problem because every route segment can only have one <code>_layout</code> file.</p><div class="language-txt-files vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt-files</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>└── &lt;root&gt;/routes</span></span>
<span class="line"><span>    ├── _layout.tsx  # applies to all routes here :(</span></span>
<span class="line"><span>    ├── about.tsx</span></span>
<span class="line"><span>    ├── career.tsx</span></span>
<span class="line"><span>    ├── archive.tsx</span></span>
<span class="line"><span>    └── contact.tsx</span></span></code></pre></div><p>We can solve this problem with route groups. A route group is a folder which has a name that is wrapped in parentheses. For example <code>(info)</code> would be considered a route group and so would <code>(marketing)</code>. This enables us to group related routes in a folder and use a different <code>_layout</code> file for each group.</p><div class="language-txt-files vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt-files</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>└── &lt;root&gt;/routes</span></span>
<span class="line"><span>    ├── (marketing)</span></span>
<span class="line"><span>    │   ├── _layout.tsx  # only applies to about.tsx and career.tsx</span></span>
<span class="line"><span>    │   ├── about.tsx</span></span>
<span class="line"><span>    │   └── career.tsx</span></span>
<span class="line"><span>    └── (info)</span></span>
<span class="line"><span>        ├── _layout.tsx  # only applies to archive.tsx and contact.tsx</span></span>
<span class="line"><span>        ├── archive.tsx</span></span>
<span class="line"><span>        └── contact.tsx</span></span></code></pre></div><blockquote><p>[warn]: Be careful about routes in different groups which match to the same URL. Such scenarios will lead to ambiguity as to which route file should be picked.</p><div class="language-txt-files vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt-files</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>└── &lt;root&gt;/routes</span></span>
<span class="line"><span>    ├── (group-1)</span></span>
<span class="line"><span>    │   └── about.tsx  # Bad: Maps to same \`/about\` url</span></span>
<span class="line"><span>    └── (group-2)</span></span>
<span class="line"><span>        └── about.tsx  # Bad: Maps to same \`/about\` url</span></span></code></pre></div></blockquote>`,24)])])}const g=a(i,[["render",o]]);export{u as __pageData,g as default};
